final_submission.code:
// Initialize all faces as unprocessed and exterior
for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin();
     current_face != triangulation.all_faces_end(); ++current_face) {
    current_face->info().processed = false;
    current_face->info().interior = false;
}

// Find a face that contains a point from the polygon (interior seed)
Triangulation::Face_handle interior_seed = nullptr;
for (std::list<Kernel::Point_3>::iterator point = points_in_polygon.begin();
     point != points_in_polygon.end() && !interior_seed; ++point) {
    Triangulation::Locate_type location_type;
    int location_vertex;
    interior_seed = triangulation.locate(*point, location_type, location_vertex);
    if (location_type == Triangulation::Locate_type::FACE) {
        interior_seed->info().interior = true;
    }
}

// If no interior seed found, use the first finite face
if (!interior_seed) {
    for (Triangulation::Finite_faces_iterator current_face = triangulation.finite_faces_begin();
         current_face != triangulation.finite_faces_end() && !interior_seed; ++current_face) {
        if (!current_face->info().processed) {
            interior_seed = current_face;
            interior_seed->info().interior = true;
        }
    }
}

// Propagate interior label using odd-even rule
std::list<Triangulation::Face_handle> face_queue;
if (interior_seed) {
    face_queue.push_back(interior_seed);
    interior_seed->info().processed = true;

    while (!face_queue.empty()) {
        Triangulation::Face_handle current_face = face_queue.front();
        face_queue.pop_front();

        // Check all three neighbors
        for (int i = 0; i < 3; ++i) {
            Triangulation::Face_handle neighbor = current_face->neighbor(i);
            if (neighbor && !neighbor->info().processed) {
                // Count interior neighbors
                int interior_neighbors = 0;
                for (int j = 0; j < 3; ++j) {
                    Triangulation::Face_handle n_neighbor = neighbor->neighbor(j);
                    if (n_neighbor && n_neighbor->info().interior) {
                        interior_neighbors++;
                    }
                }

                // Odd-even rule: if odd number of interior neighbors, mark as interior
                if (interior_neighbors % 2 == 1) {
                    neighbor->info().interior = true;
                    neighbor->info().processed = true;
                    face_queue.push_back(neighbor);
                }
            }
        }
    }
}

// Mark all unprocessed faces as exterior
for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin();
     current_face != triangulation.all_faces_end(); ++current_face) {
    if (!current_face->info().processed) {
        current_face->info().interior = false;
    }
}

